import{_ as a,o,c as r,a2 as s}from"./chunks/framework.DzNHXt93.js";const m=JSON.parse('{"title":"Form Proposal workspace","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/index.md","filePath":"proposals/index.md"}'),i={name:"proposals/index.md"};function t(n,e,d,c,l,p){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="form-proposal-workspace" tabindex="-1">Form Proposal workspace <a class="header-anchor" href="#form-proposal-workspace" aria-label="Permalink to &quot;Form Proposal workspace&quot;">​</a></h1><p>This directory contains mutable design material for Forms that have not earned a public FormRef. A document here is not a package, release, maturity claim, Host Support decision, or Service Offering.</p><p>Current family design work lives in per-family subdirectories; the first is the <a href="./edge/">Edge Platform Family</a>, whose candidates are authored under the shape-preserving boundary of <a href="./../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>.</p><p>The retained v1alpha2 Proposal set is the nine Form-backed Resources implemented by Takosumi Cloud; it remains reproducible provider-v2 preview source. Cloud provides a real workload and first host; it does not provide Takoform maturity or publication authority. Each Proposal must still pass its own portability, prior-art, fixture, migration, security, provider, package, and public-readback evidence.</p><p>Start another retained-line Proposal by copying <code>TEMPLATE.md</code> to a descriptive lowercase filename and adding one matching entry to <a href="../forms/lifecycle.json"><code>../forms/lifecycle.json</code></a> under <code>proposals</code>. Keep <code>currentForms</code> unchanged until an exact v1alpha2 <code>0.x</code> Form is carried by a v1alpha3 package and all Experimental evidence exists. Family Proposals instead live in per-family subdirectories such as <a href="./edge/"><code>edge/</code></a> and are tracked by the family candidate set (<a href="../forms/candidates/edge/v1alpha1/candidate-set.json"><code>../forms/candidates/edge/v1alpha1/candidate-set.json</code></a>), not <a href="../forms/lifecycle.json"><code>../forms/lifecycle.json</code></a>, until an Experimental transition defines family lifecycle records.</p><p>Before review, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/standard-form-conformance</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>The verifier compiles <a href="../forms/lifecycle.schema.json"><code>../forms/lifecycle.schema.json</code></a>, strictly validates the registry, checks repository-local evidence paths without following symlinks, and rejects a Proposal that claims a FormRef or release identity. Proposal review does not authorize publication.</p><p>When a Proposal is withdrawn, remove its registry entry and document unless a decision record needs to retain the design history. No public identity is reserved by a withdrawn Proposal.</p>',9)])])}const f=a(i,[["render",t]]);export{m as __pageData,f as default};
